#include <vulkan/vulkan.h>

// Generated by CMakeLists.txt from shaders/rl_dn_gradient.{slang,comp}:
// kRlDnGradient{Slang,Glsl}Spv and FUSE_RL_DN_GRADIENT_{SLANG,GLSL} when built.
#include "rl_dn_gradient_spv.h"
#endif

namespace fuse::relight::render::denoise {

namespace rr = fuse::renderer;
namespace rg = fuse::renderer::rg;

namespace {

const options::OptionBase* const kRegisteredOptions[] = {
    &RemixDenoiseOptions::useDenoiser, &DenoiseOptions::enable,        &DenoiseOptions::backend,
    &DenoiseOptions::gradients,        &DenoiseOptions::virtualMotion, &DenoiseOptions::historyFix,
    &DenoiseOptions::preblur,          &DenoiseOptions::fireflyRatio,  &DenoiseOptions::fireflySigma,
    &DenoiseOptions::atrousIterations,
};

std::string lower(std::string_view s) {
    std::string out;
    out.reserve(s.size());
    for (char c : s) {
        out.push_back(static_cast<char>(std::tolower(static_cast<unsigned char>(c))));
    }
    return out;
}

constexpr u64 kRecordBytes = 16u;
constexpr u32 kGroup = 8u;

} // namespace

void registerDenoiseOptions() {
    for (const options::OptionBase* o : kRegisteredOptions) {
        (void)o;
    }
}

rdn::RdnSettings ptDenoiseSettings() {
    rdn::RdnSettings s = rdn::rdn_preset();
    s.motionScale = 1.f; // kPtOutMotion is previous - current
    s.instanceTest = true; // kPtOutInstance: GPU-scene instance slots
    s.gradients = true;
    return s;
}

PtDenoiseConfig PtDenoiseConfig::fromOptions() {
    registerDenoiseOptions();
    PtDenoiseConfig c;
    c.enabled = RemixDenoiseOptions::useDenoiser() && DenoiseOptions::enable();
    c.backend = lower(DenoiseOptions::backend());
    c.settings = ptDenoiseSettings();
    c.settings.gradients = DenoiseOptions::gradients();
    c.settings.virtualMotion = DenoiseOptions::virtualMotion();
    c.settings.historyFix = DenoiseOptions::historyFix();
    c.settings.preblur = DenoiseOptions::preblur();
    c.settings.fireflyRatio = std::max(DenoiseOptions::fireflyRatio(), 0.f);
    c.settings.fireflySigma = std::max(DenoiseOptions::fireflySigma(), 0.f);
    c.settings.atrousIterations = static_cast<u32>(std::clamp(DenoiseOptions::atrousIterations(), 1, 5));
    return c;
}

PtDenoiseSelection selectPtDenoiser(const PtDenoiseConfig& config, std::string_view upscaler,
                                    const rdn::DenoiserRegistry& registry) {
    PtDenoiseSelection s;
    if (!config.enabled) {
        s.backend = "none";
        return s;
    }
    if (upscaler == "dlss_rr") {
        // Ray Reconstruction replaces the denoiser and the upscaler together (§5.5 "Plugins").
        s.backend = "dlss_rr";
        return s;
    }
    const std::string want = config.backend.empty() ? std::string("rdn") : config.backend;
    s.backend = "rdn";
    s.active = true;
    if (want == "rdn" || want == "svgf") {
        return s;
    }
    s.fallback = true;
    if (want == "nrd") {
        rdn::DenoiserRequirements req;
        req.signal = rdn::DenoiseSignal::Gi;
        req.method = rdn::DenoiserMethod::Reblur;
        req.allow_fallback = false;
        req.have_native_frame = false; // the Relight path tracer binds no NRD-packed textures
        req.have_hit_distance = true;
        req.have_gradients = config.settings.gradients;
        const rdn::DenoiserSelection sel = registry.select(req);
        if (sel.caps != nullptr && !sel.caps->in_tree) {
            s.reason = std::string("plugin '") + sel.caps->name +
                       "' is selectable but the Relight path tracer has no plugin frame binding yet: in-tree fallback";
        } else {
            s.reason =
                std::string("nrd unavailable (") + (sel.reason != nullptr ? sel.reason : "") + "): in-tree fallback";
        }
        return s;
    }
    s.reason = "unknown denoiser backend '" + want + "': in-tree fallback";
    return s;
}

rdn::RdnCamera cameraFromParams(const pathtrace::Word* words, bool previous) {
    const u32 b = previous ? 4u : 0u;
    rdn::RdnCamera c{};
    f32* dst[4] = {c.origin, c.right, c.up, c.forward};
    for (u32 k = 0; k < 4u; ++k) {
        dst[k][0] = words[b + k].x;
        dst[k][1] = words[b + k].y;
        dst[k][2] = words[b + k].z;
    }
    return c;
}

// --- PtDenoiser ------------------------------------------------------------------------------------------------------

PtDenoiser::PtDenoiser() = default;
PtDenoiser::~PtDenoiser() { destroy(); }

const char* PtDenoiser::kernelLanguage() const { return m_language; }

bool PtDenoiser::init(const PtDenoiserDesc& desc) {
    destroy();
    m_desc = desc;
#if defined(FUSE_VULKAN_BACKEND)
    if (desc.device == nullptr || desc.allocator == nullptr || desc.bindless == nullptr || desc.framesInFlight == 0u) {
        m_reason = "incomplete PtDenoiserDesc";
        return false;
    }
    const char* why = "";
    if (!rdn::rdn_supported(desc.device, &why)) {
        m_reason = why;
        return false;
    }
    rdn::RadianceDenoiserDesc dd{};
    dd.device = desc.device;
    dd.allocator = desc.allocator;
    dd.bindless = desc.bindless;
    dd.language = desc.language == PtDenoiseLanguage::Glsl    ? rdn::RdnKernelLanguage::Glsl
                  : desc.language == PtDenoiseLanguage::Slang ? rdn::RdnKernelLanguage::Slang
                                                              : rdn::RdnKernelLanguage::Auto;
    dd.framesInFlight = desc.framesInFlight;
    dd.hostVisible = desc.hostVisible;
    dd.hostVisibleOutput = true;
    dd.name = "relight.denoise";
    if (!m_dn.init(dd)) {
        m_reason = "radiance denoiser init failed (kernel of the requested language not built?)";
        return false;
    }
    m_initialized = true;
    m_retired.reserve(4);
    m_slotStride = (u64(2u * pathtrace::kPtParamWords) * 16u + 255u) & ~u64{255u};
    rr::BufferDesc ring{};
    ring.size = static_cast<usize>(m_slotStride * desc.framesInFlight);
    ring.usage = static_cast<rr::BufferUsage>(static_cast<u32>(rr::BufferUsage::Storage) |
                                              static_cast<u32>(rr::BufferUsage::ShaderDeviceAddress));
    ring.memoryUsage = rr::MemoryUsage::CpuToGpu;
    ring.name = "relight.denoise.params";
    if (!m_desc.allocator->createBuffer(ring, m_ring) || m_ring.mapped == nullptr || !createPipeline()) {
        destroy();
        m_reason = "gradient pipeline / parameter ring creation failed";
        return false;
    }
    m_settings = ptDenoiseSettings();
    m_reason = "ok";
    return true;
#else
    m_reason = "stub backend";
    return false;
#endif
}

void PtDenoiser::destroy() {
    if (!m_initialized) {
        return;
    }
#if defined(FUSE_VULKAN_BACKEND)
    collectRetired(~0ull);
    if (m_gradient.handle != nullptr) {
        m_desc.allocator->destroyBuffer(m_gradient);
    }
    if (m_ring.handle != nullptr) {
        m_desc.allocator->destroyBuffer(m_ring);
    }
    const VkDevice device = static_cast<VkDevice>(m_desc.device->nativeHandle());
    if (m_pipeline != nullptr) {
        vkDestroyPipeline(device, static_cast<VkPipeline>(m_pipeline), nullptr);
    }
    if (m_layoutHandle != nullptr) {
        vkDestroyPipelineLayout(device, static_cast<VkPipelineLayout>(m_layoutHandle), nullptr);
    }
#endif
    m_dn.destroy();
    m_pipeline = nullptr;
    m_layoutHandle = nullptr;
    m_gradient = rr::Buffer{};
    m_ring = rr::Buffer{};
    m_gradientQueue = 0xFFu;
    m_ringQueue = 0xFFu;
    m_strataW = m_strataH = 0;
    m_havePrev = false;
    m_frameReady = false;
    m_retired.clear();
    m_language = "none";
    m_stats = PtDenoiseStats{};
    m_initialized = false;
}

bool PtDenoiser::createPipeline() {
#if defined(FUSE_VULKAN_BACKEND)
    const u32* words = nullptr;
    usize bytes = 0;
    const bool wantSlang = m_desc.language == PtDenoiseLanguage::Auto || m_desc.language == PtDenoiseLanguage::Slang;
    const bool wantGlsl = m_desc.language == PtDenoiseLanguage::Auto || m_desc.language == PtDenoiseLanguage::Glsl;
    (void)wantSlang;
    (void)wantGlsl;
#if defined(FUSE_RL_DN_GRADIENT_SLANG)
    if (wantSlang) {
        words = kRlDnGradientSlangSpv;
        bytes = sizeof(kRlDnGradientSlangSpv);
        m_language = "slang";
    }
#endif
#if defined(FUSE_RL_DN_GRADIENT_GLSL)
    if (words == nullptr && wantGlsl) {
        words = kRlDnGradientGlslSpv;
        bytes = sizeof(kRlDnGradientGlslSpv);
        m_language = "glsl";
    }
#endif
    if (words == nullptr) {
        return false;
    }
    const VkDevice device = static_cast<VkDevice>(m_desc.device->nativeHandle());
    VkDescriptorSetLayout setLayout = static_cast<VkDescriptorSetLayout>(m_desc.bindless->layoutHandle());
    VkPushConstantRange range{VK_SHADER_STAGE_COMPUTE_BIT, 0, static_cast<u32>(sizeof(RldnPush))};
    VkPipelineLayoutCreateInfo layoutInfo{};
    layoutInfo.sType = VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO;
    layoutInfo.setLayoutCount = 1u;
    layoutInfo.pSetLayouts = &setLayout;
    layoutInfo.pushConstantRangeCount = 1;
    layoutInfo.pPushConstantRanges = &range;
    VkPipelineLayout layout = VK_NULL_HANDLE;
    if (vkCreatePipelineLayout(device, &layoutInfo, nullptr, &layout) != VK_SUCCESS) {
        return false;
    }
    m_layoutHandle = layout;
    VkShaderModuleCreateInfo moduleInfo{};
    moduleInfo.sType = VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO;
    moduleInfo.codeSize = bytes;
    moduleInfo.pCode = words;
    VkShaderModule module = VK_NULL_HANDLE;
    if (vkCreateShaderModule(device, &moduleInfo, nullptr, &module) != VK_SUCCESS) {
        return false;
    }
    VkComputePipelineCreateInfo info{};
    info.sType = VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO;
    info.flags = static_cast<VkPipelineCreateFlags>(m_desc.bindless->pipelineCreateFlags());
    info.stage.sType = VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO;
    info.stage.stage = VK_SHADER_STAGE_COMPUTE_BIT;
    info.stage.module = module;
    info.stage.pName = "main";
    info.layout = layout;
    VkPipeline pipeline = VK_NULL_HANDLE;
    const VkResult result = vkCreateComputePipelines(device, VK_NULL_HANDLE, 1, &info, nullptr, &pipeline);
    vkDestroyShaderModule(device, module, nullptr);
    m_pipeline = pipeline;
    return result == VK_SUCCESS;
#else
    return false;
#endif
}

void PtDenoiser::setSettings(const rdn::RdnSettings& settings) {
    if (settings.gradients != m_settings.gradients) {
        m_havePrev = false;
    }
    m_settings = settings;
}

void PtDenoiser::reset() {
    m_dn.reset();
    m_havePrev = false;
}

bool PtDenoiser::ensureGradientBuffer(u32 strataW, u32 strataH) {
    const u64 ns = u64(strataW) * strataH;
    const u64 samplesOffset = (ns * kRecordBytes + 255u) & ~u64{255u};
    const u64 bytes = samplesOffset + ns * kRecordBytes;
    if (m_gradient.handle != nullptr && m_strataW == strataW && m_strataH == strataH) {
        return true;
    }
    if (m_gradient.handle != nullptr) {
        m_retired.push_back(Retired{m_gradient, m_serial});
        m_gradient = rr::Buffer{};
    }
    rr::BufferDesc d{};
    d.size = static_cast<usize>(bytes);
    d.usage = static_cast<rr::BufferUsage>(static_cast<u32>(rr::BufferUsage::Storage) |
                                           static_cast<u32>(rr::BufferUsage::ShaderDeviceAddress));
    d.memoryUsage = rr::MemoryUsage::GpuToCpu;
    d.name = "relight.denoise.gradient";
    if (!m_desc.allocator->createBuffer(d, m_gradient) || m_gradient.mapped == nullptr) {
        m_gradient = rr::Buffer{};
        return false;
    }
    m_gradientQueue = 0xFFu;
    m_samplesOffset = samplesOffset;
    m_strataW = strataW;
    m_strataH = strataH;
    m_havePrev = false; // the records are new
    return true;
}

const f32* PtDenoiser::gradientRecords() const {
    return m_gradient.mapped != nullptr ? static_cast<const f32*>(m_gradient.mapped) : nullptr;
}

const f32* PtDenoiser::gradientSamples() const {
    return m_gradient.mapped != nullptr
               ? reinterpret_cast<const f32*>(static_cast<const u8*>(m_gradient.mapped) + m_samplesOffset)
               : nullptr;
}

bool PtDenoiser::beginFrame(u64 frameSerial, const pathtrace::PathTracerGpu& gpu,
                            const pathtrace::PtCompiledScene& scene, const pathtrace::PtFrameDesc& frame) {
    m_frameReady = false;
    if (!m_initialized || frame.width == 0u || frame.height == 0u || gpu.outputStride() == 0u) {
        return false;
    }
    m_serial = frameSerial;
    const u32 w = frame.width;
    const u32 h = frame.height;
    const u32 sw = (w + 2u) / 3u;
    const u32 sh = (h + 2u) / 3u;
    const bool gradients = m_settings.gradients;
    if (gradients && !ensureGradientBuffer(sw, sh)) {
        return false;
    }
    pathtrace::Word cur[pathtrace::kPtParamWords];
    scene.packParams(frame.settings, w, h, frame.frameSeed, frame.sampleBase, cur);
    const bool havePrev = m_havePrev && m_prevWidth == w && m_prevHeight == h;
    if (gradients) {
        const u64 slot = frameSerial % m_desc.framesInFlight;
        auto* dst = reinterpret_cast<pathtrace::Word*>(static_cast<u8*>(m_ring.mapped) + slot * m_slotStride);
        std::memcpy(dst, cur, sizeof(cur));
        std::memcpy(dst + pathtrace::kPtParamWords, havePrev ? m_prevWords : cur, sizeof(cur));
        const pathtrace::PtTraceBindings b = gpu.traceBindings();
        if (b.params == 0u) {
            return false;
        }
        RldnPush& p = m_record.push;
        p = RldnPush{};
        p.params = m_ring.deviceAddress + slot * m_slotStride;
        p.instances = b.instances;
        p.triangles = b.triangles;
        p.materials = b.materials;
        p.portals = b.portals;
        p.lightMap = b.lightMap;
        p.lightTable = b.lightTable;
        p.lightTree = b.lightTree;
        p.tlas = b.tlas;
        p.lut = b.lut;
        p.restirDi = 0u;
        p.records = m_gradient.deviceAddress;
        p.gradient = m_gradient.deviceAddress + m_samplesOffset;
        p.strataW = sw;
        p.strataH = sh;
        p.lightCount = b.lightCount;
        p.havePrev = havePrev ? 1u : 0u;
        m_record.self = this;
        m_record.groupsX = (sw + kGroup - 1u) / kGroup;
        m_record.groupsY = (sh + kGroup - 1u) / kGroup;
    }
    rdn::RdnFrameDesc fd{};
    fd.width = w;
    fd.height = h;
    fd.diffuse = gpu.outputAddress(pathtrace::kPtOutDiffuse);
    fd.specular = gpu.outputAddress(pathtrace::kPtOutSpecular);
    fd.normal = gpu.outputAddress(pathtrace::kPtOutNormal);
    fd.depth = gpu.outputAddress(pathtrace::kPtOutDepth);
    fd.motion = gpu.outputAddress(pathtrace::kPtOutMotion);
    fd.instance = gpu.outputAddress(pathtrace::kPtOutInstance);
    fd.gradient = gradients ? m_gradient.deviceAddress + m_samplesOffset : 0u;
    fd.camera = cameraFromParams(cur, false);
    fd.prevCamera = cameraFromParams(cur, true);
    m_dn.setSettings(m_settings);
    if (!m_dn.beginFrame(frameSerial, fd)) {
        return false;
    }
    std::memcpy(m_prevWords, cur, sizeof(cur));
    m_prevWidth = w;
    m_prevHeight = h;
    m_havePrev = gradients;
    m_stats.history = m_dn.stats().history;
    m_stats.gradients = gradients;
    m_frameReady = true;
    return true;
}

bool PtDenoiser::addPasses(rg::Graph& graph, const pathtrace::PathTracerGpu& gpu, const pathtrace::PtGraphRefs& refs) {
    (void)gpu;
    if (!m_frameReady || !refs.valid) {
        return false;
    }
    constexpr u8 kCs = rg::kStageCompute;
    rdn::RdnGraphInputs in{};
    in.add(refs.outputs);
    if (m_settings.gradients) {
        const rg::BufferRef grad = graph.importBuffer(rg::ImportedBuffer{
            m_gradient.handle, m_gradient.desc.size, m_gradientQueue, &m_gradientQueue, "relight.denoise.gradient"});
        const rg::BufferRef ring = graph.importBuffer(
            rg::ImportedBuffer{m_ring.handle, m_ring.desc.size, m_ringQueue, &m_ringQueue, "relight.denoise.params"});
        rg::PassBuilder pass = graph.addPass("relight.denoise.gradient", &PtDenoiser::recordGradient, &m_record);
        pass.use(refs.rt.tlas, rg::Access::AccelerationStructureRead, {}, kCs)
            .use(refs.statics, rg::Access::StorageRead, {}, kCs)
            .use(refs.ring, rg::Access::StorageRead, refs.ringRange, kCs)
            .use(refs.lights.ring, rg::Access::StorageRead, refs.lights.tableRange, kCs)
            .use(ring, rg::Access::StorageRead, {}, kCs)
            .use(grad, rg::Access::StorageReadWrite, {}, kCs);
        if (refs.lights.tree.tree.valid()) {
            pass.use(refs.lights.tree.tree, rg::Access::StorageRead, refs.lights.tree.range, kCs);
        }
        ++m_stats.gradientPasses;
        in.add(grad);
    }
    const rdn::RdnGraphRefs dr = m_dn.importInto(graph);
    if (!dr.valid) {
        return false;
    }
    m_dn.addPasses(graph, dr, in);
    rg::PassBuilder rb = graph.addPass("relight.denoise.readback", nullptr, nullptr);
    rb.use(dr.output, rg::Access::HostRead);
    if (m_desc.hostVisible) {
        rb.use(dr.state, rg::Access::HostRead).use(dr.work, rg::Access::HostRead);
    }
    ++m_stats.frames;
    return true;
}

void PtDenoiser::recordGradient(const rg::PassContext& context, void* user) {
#if defined(FUSE_VULKAN_BACKEND)
    const GradientRecord& r = *static_cast<const GradientRecord*>(user);
    const PtDenoiser& self = *r.self;
    VkCommandBuffer cmd = static_cast<VkCommandBuffer>(context.commandBuffer);
    vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, static_cast<VkPipeline>(self.m_pipeline));
    self.m_desc.bindless->bind(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, self.m_layoutHandle, 0);
    vkCmdPushConstants(cmd, static_cast<VkPipelineLayout>(self.m_layoutHandle), VK_SHADER_STAGE_COMPUTE_BIT, 0,
                       static_cast<u32>(sizeof(RldnPush)), &r.push);
    vkCmdDispatch(cmd, r.groupsX, r.groupsY, 1u);
#else
    (void)context;
    (void)user;
#endif
}

u32 PtDenoiser::collectRetired(u64 completedSerial) {
    if (!m_initialized) {
        return 0u;
    }
    u32 n = m_dn.collectRetired(completedSerial);
    usize keep = 0;
    for (usize i = 0; i < m_retired.size(); ++i) {
        if (m_retired[i].serial > completedSerial) {
            m_retired[keep++] = m_retired[i];
            continue;
        }
        m_desc.allocator->destroyBuffer(m_retired[i].buffer);
        ++n;
    }
    m_retired.resize(keep);
    return n;
}

} // namespace fuse::relight::render::denoise
